        // Apply reset for a couple of cycles
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
        end

        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
        end

        // Release reset
        reset = 0;

        // Step through several cycles of the LFSR sequence and verify against expected behavior
